style.css:
/* ===== COLORES ===== */

:root{
    --bg:#050505;
    --panel:rgba(18,18,18,.70);
    --border:#2f2f2f;
    --text:#f5f5f5;
    --text2:#c8c8c8;
    --shadow:rgba(255,255,255,.08);
}

/* ===== FONDO ===== */

html,
body{

    background:#050505!important;
    color:var(--text)!important;

}

/* ===== ESTRELLAS ===== */

body::before{

content:"";

position:fixed;

left:0;
top:0;

width:100%;
height:100%;

pointer-events:none;

opacity:.18;

background-image:

radial-gradient(circle,#ffffff 1px,transparent 1px),
radial-gradient(circle,#ffffff 1px,transparent 1px),
radial-gradient(circle,#ffffff 1px,transparent 1px);

background-size:

90px 90px,
140px 140px,
200px 200px;

animation:angelStars 45s linear infinite;

z-index:9998;

}

@keyframes angelStars{

from{

transform:translateY(0px);

}

to{

transform:translateY(-350px);

}

}

/* ===== ALAS ===== */

body::after{

content:"?          ?";

white-space:pre;

position:fixed;

top:18px;
left:18px;

font-size:42px;

opacity:.12;

pointer-events:none;

z-index:9999;

text-shadow:

0 0 18px white;

}

html::before{

content:"?          ?";

white-space:pre;

position:fixed;

bottom:18px;
right:18px;

font-size:42px;

opacity:.12;

pointer-events:none;

z-index:9999;

text-shadow:

0 0 18px white;

}

/* ===== EFECTO GLASS ===== */

div,
section,
article,
aside,
nav,
header,
main,
dialog{

background:var(--panel)!important;

backdrop-filter:blur(16px)!important;

border-radius:18px!important;

}

/* ===== BOTONES ===== */

button{

background:#151515!important;

border:1px solid #3a3a3a!important;

color:white!important;

border-radius:18px!important;

transition:.35s;

}

button:hover{

transform:translateY(-2px);

box-shadow:

0 0 15px rgba(255,255,255,.12);

}

/* ===== INPUTS ===== */

input,
textarea{

background:#111!important;

color:white!important;

border:1px solid #3b3b3b!important;

border-radius:16px!important;

}

/* ===== LINKS ===== */

a{

color:#ececec!important;

transition:.3s;

}

a:hover{

color:white!important;

text-shadow:

0 0 10px white;

}

/* ===== IMÁGENES ===== */

img{

transition:.4s;

}

img:hover{

filter:brightness(1.05);

}

/* ===== SCROLL ===== */

::-webkit-scrollbar{

width:10px;

}

::-webkit-scrollbar-track{

background:#090909;

}

::-webkit-scrollbar-thumb{

background:#404040;

border-radius:30px;

}

::-webkit-scrollbar-thumb:hover{

background:#5a5a5a;

}

/* ===== SELECCIÓN ===== */

::selection{

background:#ffffff33;

color:white;

}

/* ===== TRANSICIONES ===== */

*{

transition:

background .3s,

color .3s,

box-shadow .3s,

transform .3s!important;

